<template>
  <div class="data">
    <div class="dashboard-container">
      <div class="chart-box">
        <h3>疾病年龄分布</h3>
        <div id="age-distribution-chart" class="chart"></div>
      </div>
      <div class="chart-box">
        <h3>性别比例分析</h3>
        <div id="gender-ratio-chart" class="chart"></div>
      </div>
      <div class="chart-box">
        <h3>地域分布图</h3>
        <div id="region-distribution-chart" class="chart"></div>
      </div>
      <div class="chart-box">
        <h3>就诊时间分布</h3>
        <div id="visit-time-chart" class="chart"></div>
      </div>
      <div class="chart-box">
        <h3>汇总</h3>
        <div id="summary-pie-chart" class="chart"></div>
      </div>
      <div class="chart-box">
        <h3>疾病阶段分布</h3>
        <div id="disease-stage-chart" class="chart"></div>
      </div>
      <div class="chart-box">
        <h3>治疗方案统计</h3>
        <div id="treatment-plan-chart" class="chart"></div>
      </div>
      <div class="chart-box">
        <h3>复发率分析</h3>
        <div id="recurrence-rate-chart" class="chart"></div>
      </div>
      <div class="chart-box">
        <h3>筛查周期分布</h3>
        <div id="screening-cycle-chart" class="chart"></div>
      </div>
    </div>
  </div>
</template>

<script>
import * as echarts from 'echarts';
import 'echarts/lib/component/tooltip';
import 'echarts/lib/component/grid';
import 'echarts/lib/chart/bar';
import 'echarts/lib/chart/pie';
import 'echarts/lib/chart/line';
import 'echarts/lib/component/legend';
import 'echarts/lib/component/title';

export default {
  name: 'DataAnalysis',
  data() {
    return {
      searchQuery: '',
      selectedDisease: '',
      selectedType: '',
      currentPage: 1,
      itemsPerPage: 10,
      images: [],
      diseases: [],
      types: [],
      statisticsData: null,
      ageDistributionChart: null,
      genderRatioChart: null,
      regionDistributionChart: null,
      visitTimeChart: null,
      summaryPieChart: null,
      diseaseStageChart: null,
      treatmentPlanChart: null,
      recurrenceRateChart: null,
      screeningCycleChart: null,
      totalCases: 0,
      loading: true,
      resizeTimer: null
    };
  },
  computed: {
    filteredImages() {
      let filtered = this.images;

      if (this.searchQuery) {
        filtered = filtered.filter(image =>
          image.disease.includes(this.searchQuery) ||
          image.type.includes(this.searchQuery) ||
          image.description.includes(this.searchQuery)
        );
      }

      if (this.selectedDisease) {
        filtered = filtered.filter(image => image.diseaseId === this.selectedDisease);
      }

      if (this.selectedType) {
        filtered = filtered.filter(image => image.typeId === this.selectedType);
      }

      return filtered.slice(
        (this.currentPage - 1) * this.itemsPerPage,
        this.currentPage * this.itemsPerPage
      );
    },
    totalPages() {
      return Math.ceil(this.images.length / this.itemsPerPage);
    }
  },
  methods: {
    async fetchImages() {
      try {
        const response = await fetch('http://localhost:3000/api/library/images');
        const data = await response.json();
        this.images = data.images;
      } catch (error) {
        console.error('Error fetching images:', error);
      }
    },
    async fetchDiseases() {
      try {
        const response = await fetch('http://localhost:3000/api/library/diseases');
        const data = await response.json();
        this.diseases = data.diseases;
      } catch (error) {
        console.error('Error fetching diseases:', error);
      }
    },
    async fetchTypes() {
      try {
        const response = await fetch('http://localhost:3000/api/library/types');
        const data = await response.json();
        this.types = data.types;
      } catch (error) {
        console.error('Error fetching types:', error);
      }
    },
    async fetchStatistics() {
      try {
        const response = await fetch('http://localhost:3000/api/library/statistics');
        const data = await response.json();
        this.statisticsData = data.statistics;
        this.totalCases = this.statisticsData.diseaseCounts.reduce((sum, count) => sum + count, 0);
        this.initCharts();
      } catch (error) {
        console.error('Error fetching statistics:', error);
      }
    },
    initCharts() {
      this.ageDistributionChart = echarts.init(document.getElementById('age-distribution-chart'));
      this.genderRatioChart = echarts.init(document.getElementById('gender-ratio-chart'));
      this.regionDistributionChart = echarts.init(document.getElementById('region-distribution-chart'));
      this.visitTimeChart = echarts.init(document.getElementById('visit-time-chart'));
      this.summaryPieChart = echarts.init(document.getElementById('summary-pie-chart'));
      this.diseaseStageChart = echarts.init(document.getElementById('disease-stage-chart'));
      this.treatmentPlanChart = echarts.init(document.getElementById('treatment-plan-chart'));
      this.recurrenceRateChart = echarts.init(document.getElementById('recurrence-rate-chart'));
      this.screeningCycleChart = echarts.init(document.getElementById('screening-cycle-chart'));

      window.addEventListener('resize', this.resizeCharts);
      window.addEventListener('resize', this.debounceResize);

      this.renderAgeDistributionChart();
      this.renderGenderRatioChart();
      this.renderRegionDistributionChart();
      this.renderVisitTimeChart();
      this.renderSummaryPieChart();
      this.renderDiseaseStageChart();
      this.renderTreatmentPlanChart();
      this.renderRecurrenceRateChart();
      this.renderScreeningCycleChart();

      this.setupInteractions();
    },
    renderAgeDistributionChart() {
      const option = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow'
          }
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '10%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          data: ['0-18', '19-35', '36-50', '51-65', '65+']
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          name: '数量',
          type: 'bar',
          data: this.statisticsData.ageCounts,
          itemStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
              { offset: 0, color: '#64b5f6' },
              { offset: 1, color: '#1e88e5' }
            ])
          },
          animationDuration: 1000
        }]
      };
      this.ageDistributionChart.setOption(option);
    },
    renderGenderRatioChart() {
      const option = {
        tooltip: {
          trigger: 'item'
        },
        legend: {
          orient: 'vertical',
          right: 10,
          data: ['男性', '女性']
        },
        series: [{
          name: '性别比例',
          type: 'pie',
          radius: ['40%', '70%'],
          avoidLabelOverlap: false,
          itemStyle: {
            borderRadius: 10,
            borderColor: '#fff',
            borderWidth: 2
          },
          label: {
            show: false,
            position: 'center'
          },
          emphasis: {
            label: {
              show: true,
              fontSize: '18',
              fontWeight: 'bold'
            }
          },
          labelLine: {
            show: false
          },
          data: [
            { value: this.statisticsData.genderCounts.male, name: '男性', itemStyle: { color: '#4fc3f7' } },
            { value: this.statisticsData.genderCounts.female, name: '女性', itemStyle: { color: '#ffcdd2' } }
          ]
        }]
      };
      this.genderRatioChart.setOption(option);
    },
    renderRegionDistributionChart() {
      const option = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow'
          }
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '10%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          data: this.statisticsData.regionCategories
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          name: '数量',
          type: 'bar',
          data: this.statisticsData.regionCounts,
          itemStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
              { offset: 0, color: '#ff9800' },
              { offset: 1, color: '#f57c00' }
            ])
          },
          animationDuration: 1000
        }]
      };
      this.regionDistributionChart.setOption(option);
    },
    renderVisitTimeChart() {
      const option = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow'
          }
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '10%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          data: ['2018', '2019', '2020', '2021','2022', '2023', '2024', '2025']
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          name: '数量',
          type: 'line',
          data: this.statisticsData.visitTimeCounts,
          itemStyle: {
            color: '#4caf50'
          },
          lineStyle: {
            width: 3
          },
          areaStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
              { offset: 0, color: 'rgba(76, 175, 80, 0.5)' },
              { offset: 1, color: 'rgba(76, 175, 80, 0.1)' }
            ])
          },
          animationDuration: 1000
        }]
      };
      this.visitTimeChart.setOption(option);
    },
    renderSummaryPieChart() {
      const option = {
        tooltip: {
          trigger: 'item'
        },
        legend: {
          top: '5%',
          left: 'center'
        },
        series: [{
          name: '疾病分布',
          type: 'pie',
          radius: ['40%', '70%'],
          avoidLabelOverlap: false,
          itemStyle: {
            borderRadius: 10,
            borderColor: '#fff',
            borderWidth: 2
          },
          label: {
            show: false,
            position: 'center'
          },
          emphasis: {
            label: {
              show: true,
              fontSize: '18',
              fontWeight: 'bold'
            }
          },
          labelLine: {
            show: false
          },
          data: this.statisticsData.diseaseCategories.map((category, index) => ({
            name: category,
            value: this.statisticsData.diseaseCounts[index],
            itemStyle: {
              color: ['#ffcdd2', '#bbdefb', '#c8e6c9', '#ffecb3', '#b3e5fc'][index % 5]
            }
          }))
        }]
      };
      this.summaryPieChart.setOption(option);
    },
    renderDiseaseStageChart() {
      const option = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow'
          }
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '10%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          data: ['早期', '中期', '晚期']
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          name: '数量',
          type: 'bar',
          data: this.statisticsData.diseaseStageCounts,
          itemStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
              { offset: 0, color: '#cddc39' },
              { offset: 1, color: '#afbd01' }
            ])
          },
          animationDuration: 1000
        }]
      };
      this.diseaseStageChart.setOption(option);
    },
    renderTreatmentPlanChart() {
      const option = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow'
          }
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '10%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          data: this.statisticsData.treatmentPlanCategories
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          name: '数量',
          type: 'bar',
          data: this.statisticsData.treatmentPlanCounts,
          itemStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
              { offset: 0, color: '#ffb74d' },
              { offset: 1, color: '#f57c00' }
            ])
          },
          animationDuration: 1000
        }]
      };
      this.treatmentPlanChart.setOption(option);
    },
    renderRecurrenceRateChart() {
      const option = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow'
          }
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '10%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          data: ['0-10%', '11-20%', '21-30%', '31-40%', '41-50%', '50%+']
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          name: '数量',
          type: 'bar',
          data: this.statisticsData.recurrenceRateCounts,
          itemStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
              { offset: 0, color: '#ff9e80' },
              { offset: 1, color: '#f4511e' }
            ])
          },
          animationDuration: 1000
        }]
      };
      this.recurrenceRateChart.setOption(option);
    },
    renderScreeningCycleChart() {
      const option = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow'
          }
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '10%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          data: ['3个月', '6个月', '1年', '2年', '3年', '3年以上']
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          name: '数量',
          type: 'bar',
          data: this.statisticsData.screeningCycleCounts,
          itemStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
              { offset: 0, color: '#90caf9' },
              { offset: 1, color: '#1e88e5' }
            ])
          },
          animationDuration: 1000
        }]
      };
      this.screeningCycleChart.setOption(option);
    },
    setupInteractions() {
      this.ageDistributionChart.on('click', (params) => {
        this.updatePieChart(params.name);
        this.filterImagesByAge(params.name);
      });

      this.genderRatioChart.on('click', (params) => {
        this.updatePieChart(params.name);
        this.filterImagesByGender(params.name);
      });

      this.regionDistributionChart.on('click', (params) => {
        this.updatePieChart(params.name);
        this.filterImagesByRegion(params.name);
      });

      this.visitTimeChart.on('click', (params) => {
        this.updatePieChart(params.name);
        this.filterImagesByVisitTime(params.name);
      });

      this.diseaseStageChart.on('click', (params) => {
        this.updatePieChart(params.name);
        this.filterImagesByDiseaseStage(params.name);
      });

      this.treatmentPlanChart.on('click', (params) => {
        this.updatePieChart(params.name);
        this.filterImagesByTreatmentPlan(params.name);
      });

      this.recurrenceRateChart.on('click', (params) => {
        this.updatePieChart(params.name);
        this.filterImagesByRecurrenceRate(params.name);
      });

      this.screeningCycleChart.on('click', (params) => {
        this.updatePieChart(params.name);
        this.filterImagesByScreeningCycle(params.name);
      });
    },
    updatePieChart(dimension) {
      const pieOption = this.summaryPieChart.getOption();
      pieOption.series[0].data = this.statisticsData.diseaseCategories.map((category, index) => {
        const baseValue = this.statisticsData.diseaseCounts[index];
        if (category === dimension) {
          return {
            name: category,
            value: baseValue * 1.5,
            itemStyle: { color: '#ffcdd2' }
          };
        }
        return {
          name: category,
          value: baseValue * 0.8,
          itemStyle: { color: ['#ffcdd2', '#bbdefb', '#c8e6c9', '#ffecb3', '#b3e5fc'][index % 5] }
        };
      });
      this.summaryPieChart.setOption(pieOption);
    },
    filterImagesByAge(ageRange) {
      this.images = this.images.filter(image => image.ageRange === ageRange);
      this.currentPage = 1;
    },
    filterImagesByGender(gender) {
      this.images = this.images.filter(image => image.gender === gender);
      this.currentPage = 1;
    },
    filterImagesByRegion(region) {
      this.images = this.images.filter(image => image.region === region);
      this.currentPage = 1;
    },
    filterImagesByVisitTime(visitTime) {
      this.images = this.images.filter(image => image.visitTime === visitTime);
      this.currentPage = 1;
    },
    filterImagesByDiseaseStage(stage) {
      this.images = this.images.filter(image => image.diseaseStage === stage);
      this.currentPage = 1;
    },
    filterImagesByTreatmentPlan(plan) {
      this.images = this.images.filter(image => image.treatmentPlan === plan);
      this.currentPage = 1;
    },
    filterImagesByRecurrenceRate(rate) {
      this.images = this.images.filter(image => image.recurrenceRate === rate);
      this.currentPage = 1;
    },
    filterImagesByScreeningCycle(cycle) {
      this.images = this.images.filter(image => image.screeningCycle === cycle);
      this.currentPage = 1;
    },
    resizeCharts() {
      if (this.ageDistributionChart) this.ageDistributionChart.resize();
      if (this.genderRatioChart) this.genderRatioChart.resize();
      if (this.regionDistributionChart) this.regionDistributionChart.resize();
      if (this.visitTimeChart) this.visitTimeChart.resize();
      if (this.summaryPieChart) this.summaryPieChart.resize();
      if (this.diseaseStageChart) this.diseaseStageChart.resize();
      if (this.treatmentPlanChart) this.treatmentPlanChart.resize();
      if (this.recurrenceRateChart) this.recurrenceRateChart.resize();
      if (this.screeningCycleChart) this.screeningCycleChart.resize();
    },
    debounceResize() {
      clearTimeout(this.resizeTimer);
      this.resizeTimer = setTimeout(this.resizeCharts, 200);
    },
    searchImages() {
      this.currentPage = 1;
    },
    previousPage() {
      if (this.currentPage > 1) {
        this.currentPage--;
      }
    },
    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++;
      }
    },
    simulateData() {
      const diseaseCategories = ['糖尿病视网膜病变', '黄斑变性', '青光眼', '白内障', '其他'];
      const regionCategories = ['华东', '华北', '华南', '西南', '西北', '东北'];
      const treatmentPlanCategories = ['激光治疗', '药物治疗', '手术治疗', '观察随访', '其他'];
      const visitTimeCategories = ['2022Q1', '2022Q2', '2022Q3', '2022Q4', '2023Q1', '2023Q2', '2023Q3', '2023Q4'];
      const diseaseStageCategories = ['早期', '中期', '晚期'];
      const recurrenceRateCategories = ['0-10%', '11-20%', '21-30%', '31-40%', '41-50%', '50%+'];
      const screeningCycleCategories = ['3个月', '6个月', '1年', '2年', '3年', '3年以上'];

      const diseaseCounts = diseaseCategories.map(() => Math.floor(Math.random() * 1000));
      const ageCounts = [Math.floor(Math.random() * 200), Math.floor(Math.random() * 300), Math.floor(Math.random() * 500), Math.floor(Math.random() * 300), Math.floor(Math.random() * 200)];
      const regionCounts = regionCategories.map(() => Math.floor(Math.random() * 600));
      const visitTimeCounts = visitTimeCategories.map(() => Math.floor(Math.random() * 300));
      const diseaseStageCounts = diseaseStageCategories.map(() => Math.floor(Math.random() * 400));
      const treatmentPlanCounts = treatmentPlanCategories.map(() => Math.floor(Math.random() * 300));
      const recurrenceRateCounts = recurrenceRateCategories.map(() => Math.floor(Math.random() * 200));
      const screeningCycleCounts = screeningCycleCategories.map(() => Math.floor(Math.random() * 150));
      const genderCounts = { male: Math.floor(Math.random() * 1500), female: Math.floor(Math.random() * 1500) };

      this.statisticsData = {
        diseaseCategories,
        diseaseCounts,
        ageCategories: ['0-18', '19-35', '36-50', '51-65', '65+'],
        ageCounts,
        regionCategories,
        regionCounts,
        visitTimeCategories,
        visitTimeCounts,
        diseaseStageCategories,
        diseaseStageCounts,
        treatmentPlanCategories,
        treatmentPlanCounts,
        recurrenceRateCategories,
        recurrenceRateCounts,
        screeningCycleCategories,
        screeningCycleCounts,
        genderCounts
      };

      this.totalCases = diseaseCounts.reduce((sum, count) => sum + count, 0);
    }
  },
  mounted() {
    this.simulateData();
    this.initCharts();
    this.loading = false;
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.resizeCharts);
    window.removeEventListener('resize', this.debounceResize);
    if (this.ageDistributionChart) this.ageDistributionChart.dispose();
    if (this.genderRatioChart) this.genderRatioChart.dispose();
    if (this.regionDistributionChart) this.regionDistributionChart.dispose();
    if (this.visitTimeChart) this.visitTimeChart.dispose();
    if (this.summaryPieChart) this.summaryPieChart.dispose();
    if (this.diseaseStageChart) this.diseaseStageChart.dispose();
    if (this.treatmentPlanChart) this.treatmentPlanChart.dispose();
    if (this.recurrenceRateChart) this.recurrenceRateChart.dispose();
    if (this.screeningCycleChart) this.screeningCycleChart.dispose();
  }
};
</script>

<style scoped>
@import '@/assets/css/global.css';
@import '@/assets/css/header.css';
@import '@/assets/css/data-analysis.css';
</style>